<script lang="ts">
 import { onMount } from 'svelte';
 import { Orbit,SlidersHorizontal,ChartNoAxesCombined,Save,Download,Upload,Info,X,Plus,MessageSquare } from 'lucide-svelte';
 import { simulationState,status,save,startClock } from './lib/store';
 import { workspaceUi } from './lib/workspace-ui';
 import { defaultSimulationState,validateSimulationState } from './lib/simulation-state';
 import { positions,type Ephemeris } from './lib/ephemeris';
 import { withSatellitePositions } from './lib/satellites';
 import { focus } from './lib/focus';
 import ViewTree from './components/ViewTree.svelte';
 import Settings from './components/Settings.svelte';
 import Charts from './components/Charts.svelte';
 import Timeline from './components/Timeline.svelte';
 import ScenarioPicker from './components/ScenarioPicker.svelte';
 import ResearchAgent from './components/ResearchAgent.svelte';
 import AgentAccess from './components/AgentAccess.svelte';
 import {missionViews} from './lib/mission-views';
 import MissionViewport from './components/MissionViewport.svelte';
 import MissionTimeline from './components/MissionTimeline.svelte';
 let researchAgentOpen=$state(false),researchAgentWidth=$state(420);
 let agentAccessOpen=$state(false);
 let setupRequest=$state<{id:string;text:string}|null>(null);
 let setupResult:((error?:string)=>void)|undefined;
 function setupScenario(text:string){
  if(setupRequest)return Promise.reject(new Error('A scenario setup request is already pending.'));
  researchAgentOpen=true;setupRequest={id:crypto.randomUUID(),text};
  return new Promise<void>((resolve,reject)=>{const timer=setTimeout(()=>setupResult?.('Scenario submission timed out. Check the research conversation before trying again; it may have been received.'),30000);setupResult=(error)=>{clearTimeout(timer);setupRequest=null;setupResult=undefined;if(error)reject(new Error(error));else resolve();};});
 }
 let data=$state.raw<Ephemeris|null>(null),error=$state('');let fileInput:HTMLInputElement;
 const simulationTime=$derived($simulationState.time);
 const physicalPositions=$derived(data?withSatellitePositions(positions(data,simulationTime),simulationTime):{});
 onMount(()=>startClock());
 onMount(()=>{const open=()=>researchAgentOpen=true;window.addEventListener('workspace-agent-open',open);return()=>window.removeEventListener('workspace-agent-open',open);});
 // Guided missions have their own historical context; load the modern dataset
 // only when returning to the normal workspace, avoiding competing startup work.
 $effect(()=>{if($simulationState.mission||data)return;const abort=new AbortController();error='';fetch('/data/ephemeris.json',{signal:abort.signal}).then(r=>{if(!r.ok)throw new Error('Orbital data unavailable');return r.json();}).then(d=>{if(!abort.signal.aborted)data=d;}).catch(e=>{if(e.name!=='AbortError')error=e.message;});return()=>abort.abort();});
 function exportSession(){save();const url=URL.createObjectURL(new Blob([JSON.stringify($simulationState,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='solar-simulation-state.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 async function importSession(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;try{if(file.size>100000)throw new Error('Simulation state file is too large.');const next=validateSimulationState(JSON.parse(await file.text()));next.playing=false;if(next.mission)next.mission.playing=false;simulationState.set(next);save();status.set('Simulation state imported · paused');}catch(e){status.set(`Import failed: ${(e as Error).message}`);}input.value='';}
</script>
<svelte:head><meta name="description" content="A personal solar observatory. Explore the planets and moons through synchronized, independent views."/></svelte:head>
<div class="app-shell" class:research-agent-open={researchAgentOpen} style:--research-agent-width={`${researchAgentWidth}px`}>
 <header class="app-header"><a class="brand" href="/" aria-label="Solar Observatory home"><div class="brand-symbol"><Orbit size={26} strokeWidth={1.2}/></div><div><strong>SOLAR<span>OBSERVATORY</span></strong><small>A WINDOW INTO OUR SOLAR SYSTEM</small></div></a><div class="header-center"><span class="live-dot"></span>EXPLORATION WORKSPACE</div><nav aria-label="Main menu"><button class:pressed={$workspaceUi.charts} title="Distance charts" aria-label="Toggle charts" onclick={()=>$workspaceUi.charts=!$workspaceUi.charts}><ChartNoAxesCombined size={19}/></button><button class:pressed={$workspaceUi.settings} title="View settings" aria-label="Toggle settings" onclick={()=>$workspaceUi.settings=!$workspaceUi.settings}><SlidersHorizontal size={19}/></button><button class:pressed={researchAgentOpen} title="Ask your research companion" aria-label="Open research companion" onclick={()=>researchAgentOpen=!researchAgentOpen}><MessageSquare size={19}/></button><div class="divider"></div><button title="Save session" aria-label="Save session" onclick={save}><Save size={18}/></button><button title="Export simulation state" aria-label="Export simulation state" onclick={exportSession}><Download size={18}/></button><button title="Import simulation state" aria-label="Import simulation state" disabled={!!$simulationState.mission} onclick={()=>fileInput.click()}><Upload size={18}/></button><button title="About & sources" aria-label="About and sources" onclick={()=>$workspaceUi.about=true}><Info size={18}/></button></nav><input class="hidden" type="file" accept="application/json,.json" bind:this={fileInput} onchange={importSession}/></header>
 <div class="workspace-bar"><div><span class="eyebrow">SIMULATION</span><input aria-label="SimulationState name" disabled={!!$simulationState.mission} maxlength="120" value={$simulationState.name} onchange={e=>simulationState.update(s=>({...s,name:e.currentTarget.value}))}/></div><ScenarioPicker onsetup={setupScenario}/><div class="quick-views"><span>EXPLORE</span><button disabled={!!$simulationState.mission} onclick={()=>focus($simulationState.active,'sun')}>Solar system</button><button disabled={!!$simulationState.mission} onclick={()=>focus($simulationState.active,'earth')}>Earth & Moon</button><button disabled={!!$simulationState.mission} onclick={()=>focus($simulationState.active,'saturn')}>Saturn</button></div>{#if __HOSTED_ENABLED__}<button class="new-session" aria-expanded={agentAccessOpen} onclick={()=>agentAccessOpen=!agentAccessOpen}>Agent access</button>{/if}<button class="new-session" disabled={!!$simulationState.mission} title="Save current session and start a new one" onclick={()=>{exportSession();simulationState.set(defaultSimulationState());save();}}><Plus size={14}/> New</button></div>
 <main><div class="view-area">{#if $simulationState.mission}<MissionViewport/>{:else if error}<div class="loading"><h2>Unable to load the observatory</h2><p>{error}. Run <code>npm run data</code> to restore the bundled data.</p><button onclick={()=>location.reload()}>Retry</button></div>{:else if data}<ViewTree node={$simulationState.layout} {data} positions={physicalPositions}/>{:else}<div class="loading"><Orbit size={40}/><h2>Preparing your observatory</h2><p>Loading orbital elements from the local dataset…</p></div>{/if}</div>{#if !$simulationState.mission&&$workspaceUi.settings}<Settings positions={physicalPositions} onclose={()=>$workspaceUi.settings=false}/>{/if}{#if !$simulationState.mission&&$workspaceUi.charts&&data}<Charts {data} onclose={()=>$workspaceUi.charts=false}/>{/if}{#if import.meta.env.MODE === 'companion'}{#await import('../companion/Connection.svelte') then module}<module.default/>{/await}{/if}</main>
 {#if $simulationState.mission}<MissionTimeline/>{:else}<Timeline/>{/if}

 <div class="status-bar"><span role="status">{$status}</span><span>JPL HORIZONS <i>·</i> {$simulationState.mission?'APOLLO 11 · JULY 1969':'1990–2030'} <i>·</i> {$simulationState.mission?missionViews($simulationState.mission).length:$simulationState.views.length} {($simulationState.mission?missionViews($simulationState.mission).length:$simulationState.views.length)===1?'VIEW':'VIEWS'}</span></div>
</div>
{#if $workspaceUi.about}<div class="modal-backdrop" role="presentation"><div class="about-modal" role="dialog" aria-modal="true" aria-label="About Solar Observatory" tabindex="-1"><button class="modal-close" aria-label="Close about" onclick={()=>$workspaceUi.about=false}><X size={20}/></button><Orbit size={32}/><span class="eyebrow">SOLAR OBSERVATORY / 0.1</span><h1>A shared universe.<br/>Your perspective.</h1><p>Eight planets. Twelve moons. One shared clock. Split the sky into independent views, follow a world, and return to a saved exploration.</p><h3>Data & accuracy</h3><p>Orbital elements downloaded from <a href="https://ssd.jpl.nasa.gov/horizons/" target="_blank" rel="noreferrer">NASA/JPL Horizons</a>. Planet elements are sampled every 8 days; moon elements daily. Kepler propagation is smoothly blended between epochs. Positions are approximate and have not yet been checked against reference ephemerides.</p><p>J2000 ecliptic coordinates. Dates are shown in UTC; conversion to ephemeris time assumes 37 leap seconds. Axial rotation and pole directions use the polynomial terms of <a href="https://naif.jpl.nasa.gov/pub/naif/generic_kernels/pck/pck00011.tpc" target="_blank" rel="noreferrer">NASA/JPL NAIF planetary rotation models</a>. Periodic libration/nutation, differential solar rotation, atmospheric winds and eclipses are not modeled. Texture longitude registration is approximate. Untextured moons use representative colors.</p><h3>Earth close-ups</h3><p>Earth uses adaptive globe detail, registered surface maps, ocean reflections, animated cloud layers and approximate atmospheric scattering. Clouds follow simulation time and cast soft ground shadows; city lights appear on the night side. Weather, seasonal imagery and city lights are illustrative, not historical conditions for the selected date. Surface terrain detail changes shading, not physical elevations.</p><h3>Earth satellites</h3><p>Hubble and the ISS use bundled <a href="https://celestrak.org/NORAD/documentation/gp-data-formats.php" target="_blank" rel="noreferrer">CelesTrak / NORAD orbital-elements snapshots</a> propagated with SGP4. Satellites are visible from their orbital start dates. SGP4 is used within three days of the bundled epoch; beyond this, a continuous two-body illustrative orbit is used. Historical position, altitude, manoeuvres and station assembly are not reconstructed. TEME coordinates are converted through GMST and the existing IAU Earth orientation; polar motion and nutation are omitted. The simplified telescope and solar-panel mesh uses <a href="https://science.nasa.gov/mission/hubble/observatory/design/" target="_blank" rel="noreferrer">NASA dimensions</a>. The simplified ISS truss, modules and solar-array wings use <a href="https://www.nasa.gov/international-space-station/space-station-facts-and-figures/" target="_blank" rel="noreferrer">NASA station dimensions</a>; attitude is illustrative. Close-range models: <a href="https://science.nasa.gov/3d-resources/international-space-station-iss-b/" target="_blank" rel="noreferrer">NASA/Michael D. Carbajal ISS (B)</a> and <a href="https://science.nasa.gov/3d-resources/hubble-space-telescope-a/" target="_blank" rel="noreferrer">DigitalSpace Corporation / NASA Hubble (A)</a>. Simplified meshes remain at a distance. Satellite magnification does not alter physical orbital distances.</p><h3>Image credits</h3><p>Sun, planet and Moon maps by <a href="https://www.solarsystemscope.com/textures/" target="_blank" rel="noreferrer">Solar System Scope / INOVE</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Rendered with lighting and display magnification. The star field uses the full-resolution 8K HDR J2000 map from <a href="https://svs.gsfc.nasa.gov/4851/" target="_blank" rel="noreferrer">NASA/Goddard Space Flight Center Scientific Visualization Studio</a> (Ernie Wright), Deep Star Maps 2020. Gaia DR2: ESA/Gaia/DPAC. Constellation figures are based on designs for the IAU by Alan MacRobert, Sky and Telescope (Roger Sinnott and Rick Fienberg). Sky brightness is enhanced for visibility; proper motion and stellar parallax are not modeled.</p><h3>On the horizon</h3><p>Physical rocket flight, asteroids, more satellites, Earth-surface observations, and a configurable LLM connection through a local server.</p><button class="primary-button" onclick={()=>$workspaceUi.about=false}>Back to exploring</button></div></div>{/if}


{#if researchAgentOpen}<ResearchAgent request={setupRequest} onresult={error=>setupResult?.(error)} onclose={()=>{setupResult?.("Scenario submission cancelled. Check the conversation before trying again.");researchAgentOpen=false;}} bind:width={researchAgentWidth}/>{/if}
{#if __HOSTED_ENABLED__}<div hidden={!agentAccessOpen}><AgentAccess onclose={()=>agentAccessOpen=false}/></div>{/if}

<style>
 .app-shell.research-agent-open{width:calc(100% - var(--research-agent-width,420px))}
 @media(max-width:900px){.app-shell.research-agent-open{width:100%}}

 .workspace-bar{gap:14px;overflow-x:auto;scrollbar-width:thin}
 .workspace-bar>div:first-child{flex-shrink:0}
 .workspace-bar :global(.quick-views){flex-shrink:0}
 .workspace-bar .new-session{flex-shrink:0}
</style>

